INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "唐昭宗赐魏国夫人陈氏给李克用", "start_year": 895, "end_year": 895, "time_original": "895年十月戊子", "dynasty": "唐", "description": "唐昭宗将魏国夫人陈氏赐给李克用；史书称其才色冠后宫。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "3ede1fe6-2e1d-5a68-a87a-d9cc77da2160"}, {"title": "李克用命李罕之李存信急攻梨园", "start_year": 895, "end_year": 895, "time_original": "895年十月戊子后条；确日未另载", "dynasty": "唐", "description": "李克用命李罕之、李存信等加紧进攻梨园。", "phases": [], "location_name": "梨园", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "24fbd60a-c405-59b1-b198-2a157aec2edf"}, {"title": "梨园守军粮尽弃城，李罕之等邀击克三寨", "start_year": 895, "end_year": 895, "time_original": "895年十月急攻梨园后条；确日未载", "dynasty": "唐", "description": "城内粮尽，守军弃城逃走，李罕之等截击，杀万余人，攻克梨园等三寨。", "phases": [], "location_name": "梨园等三寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "84c4df9f-52ac-59e5-a145-c2c19abcb65e"}, {"title": "梨园战后获王行瑜子知进与李元福", "start_year": 895, "end_year": 895, "time_original": "895年十月克梨园条；确日未另载", "dynasty": "唐", "description": "李克用军俘王行瑜之子知进及大将李元福等人。", "phases": [], "location_name": "梨园等三寨", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "63820e6d-4b1c-5edf-a881-a3d4c74401ea"}, {"title": "李克用进驻梨园", "start_year": 895, "end_year": 895, "time_original": "895年十月克三寨后条；确日未另载", "dynasty": "唐", "description": "李克用进军驻梨园。", "phases": [], "location_name": "梨园", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1ec8a6e3-7677-59df-9fe4-b88883d895f5"}, {"title": "王行约王行实烧宁州逃走", "start_year": 895, "end_year": 895, "time_original": "895年十月庚寅", "dynasty": "唐", "description": "王行约、王行实烧宁州后逃走。", "phases": [], "location_name": "宁州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0356ea1e-6951-5c5b-81b2-0df8b48bbf3b"}, {"title": "李克用奏请苏文建为静难，催赴镇兼理宁州", "start_year": 895, "end_year": 895, "time_original": "895年十月王氏兄弟遁后条；确日未载", "dynasty": "唐", "description": "李克用奏请以匡国节度使苏文建为静难节度使，催其赴镇，暂以宁州治理并招抚降人。", "phases": [], "location_name": "静难、宁州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4dd899b7-923d-5d96-aed7-7e5743140938"}, {"title": "唐昭宗迁居大内", "start_year": 895, "end_year": 895, "time_original": "895年十月条；确日未载", "dynasty": "唐", "description": "唐昭宗迁居大内。", "phases": [], "location_name": "大内", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a4915b11-334c-5954-a338-bdeadaef1778"}, {"title": "朱温遣葛从周击兖州并以大军继，癸卯围城", "start_year": 895, "end_year": 895, "time_original": "895年十月癸卯围城；派兵日未另载", "dynasty": "唐", "description": "朱温派都将葛从周攻兖州，自己率大军随后，癸卯围兖州。", "phases": [], "location_name": "兗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5fa23c83-521f-5e0c-af6c-cdaa86ba4a48"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

